/// (按鍵, 期望的詞)。都是「第一個字的單字排序不是第一名」的詞——
/// 那正是最容易被拆錯的情況。
const CASES: &[(&str, &str)] = &[
    ("rup wu0 ", "今天"), // 今：單字排第 2（金第 1）
    ("ru04au04", "見面"), // 見：單字排第 2（間第 1）
    ("h0 wu/ ", "餐廳"),  // 餐：單字排第 2
    ("au/6wu0 ", "明天"), // 明：現在單字排第 1 了
    ("wu0 fu4", "天氣"),
    ("su3cl3", "你好"),
    ("2k7wu0 fu4", "的天氣"),
    ("rup wu0 wu0 fu4cp3cl3", "今天天氣很好"),
    ("g42k7", "是的"),
];
